#!/usr/bin/env bash
# tail-tones S14 — deterministic log fixture generator (plan §8: "fixtures
# generated by scripts/gen-logs.sh (deterministic seed)").
#
# Writes test-fixtures/{logback,json,logfmt,docker,mixed,storm}.log.
# DETERMINISM CONTRACT (S14 goldens depend on it):
#   - every byte depends ONLY on the fixture name + TAILTONES_FIXTURE_SEED
#     (default 1337);
#   - NO wall clock: timestamps are synthesized from a fixed base
#     (2026-11-09 10:00:00, +100 ms per line) — rerunning NEVER changes bytes;
#   - NO dependency on awk's implementation-defined rand(): POSIX does not pin
#     its sequence, so the generator embeds its OWN Park–Miller LCG (rnd()
#     below; 16807/2147483647, exact under IEEE doubles, identical in every
#     awk ever written). Cross-host reproducible by construction.
#   - regeneration must be byte-identical: `scripts/gen-logs.sh && git diff
#     --exit-code test-fixtures/` is the check (FixtureE2eSpec pins it
#     inside `sbt test`).
#
# Usage:
#   scripts/gen-logs.sh                            # (re)write all fixtures
#   TAILTONES_FIXTURE_SEED=7 scripts/gen-logs.sh   # different, still stable
#   OUT=/tmp/x scripts/gen-logs.sh                 # alt output dir (smoke)
set -euo pipefail

cd "$(dirname "$0")/.."
OUT="${OUT:-test-fixtures}"
SEED="${TAILTONES_FIXTURE_SEED:-1337}"
mkdir -p "$OUT"

# Every program below gets the same prelude: the LCG (state variable `s`).
PRELUDE='
function rnd(  t) { s = (s * 16807) % 2147483647; return s / 2147483647 }
function pick(n)  { return int(rnd() * n) }          # 0 .. n-1
BEGIN { s = seed % 2147483647; if (s <= 0) s = 1
'

gen() { # gen <name> <lines> <awk-body-without-BEGIN>
  local name="$1" lines="$2" body="$3"
  awk -v n="$lines" -v seed="$SEED" "$PRELUDE$body
}" > "$OUT/$name.log"
  printf '%s\n' "$OUT/$name.log ($(wc -l < "$OUT/$name.log" | tr -d ' ') lines)"
}

# ---------------------------------------------------------------- logback
# Logback §5.3 shape: `yyyy-MM-dd HH:mm:ss,SSS LEVEL logger - message`.
# ~info-heavy + occasional warn/debug/error; every 37th line is a raw
# keyword line (no timestamp) so the fixture exercises the logback AND
# keyword legs of the auto chain.
gen logback 120 '
  split("com.acme.orders.Service com.acme.pay.Client com.acme.cache.Store com.acme.http.Router", L, " ")
  split("order accepted payment ok cache miss request routed batch scheduled pool warm", M, " ")
  t = 1762696800000
  for (i = 1; i <= n; i++) {
    lvl = "INFO"; r = rnd()
    if      (r < 0.05) lvl = "WARN"
    else if (r < 0.09) lvl = "DEBUG"
    else if (r < 0.10) lvl = "ERROR"
    ts = t + i * 100
    ms = int(ts % 1000); s0 = int(ts / 1000) % 60
    mn = int(ts / 60000) % 60; hh = int(ts / 3600000) % 24
    stamp = sprintf("2026-11-09 %02d:%02d:%02d,%03d", hh, mn, s0, ms)
    lg = L[pick(4)+1]; msg = M[pick(7)+1]
    if (i % 37 == 0) print "raw keyword line with " msg " here"   # keyword leg
    else printf "%s %s %s - %s %d\n", stamp, lvl, lg, msg, i
  }'

# ------------------------------------------------------------------- json
# JsonProfile: one JSON object per line; level from level/lvl/severity;
# deliberately one object per 29 with NO level key (auto → keyword/Neutral)
# and per-43 nested json-in-log.
gen json 120 '
  t = 1762696800000
  for (i = 1; i <= n; i++) {
    r = rnd(); lvl = "info"
    if      (r < 0.06) lvl = "warn"
    else if (r < 0.09) lvl = "debug"
    else if (r < 0.11) lvl = "error"
    ts = t + i * 100
    if (i % 29 == 0)
      printf "{\"time\":%d,\"msg\":\"no level key here %d\",\"k\":\"v\"}\n", ts, i
    else if (i % 43 == 0)
      printf "{\"lvl\":\"%s\",\"nested\":\"{\\\"level\\\":\\\"warn\\\",\\\"why\\\":\\\"inner %d\\\"}\"}\n", lvl, i
    else if (i % 11 == 0)
      printf "{\"severity\":\"%s\",\"trace_id\":\"%08x\",\"msg\":\"svc handler done %d\"}\n", lvl, int(rnd()*65536), i
    else
      printf "{\"level\":\"%s\",\"time\":%d,\"logger\":\"svc.http\",\"msg\":\"request handled %d\"}\n", lvl, ts, i
  }'

# ----------------------------------------------------------------- logfmt
# Logfmt: k=v incl. quoted values with backslash escapes; level key rotates
# level/sev/severity; per-23 line has a non-mappable level=nope BEFORE the
# real severity= (pins the "recognized key with unmappable value continues"
# rule).
gen logfmt 120 '
  for (i = 1; i <= n; i++) {
    r = rnd(); lvl = "info"
    if      (r < 0.05) lvl = "warn"
    else if (r < 0.08) lvl = "debug"
    else if (r < 0.09) lvl = "error"
    k = "level"; rr = rnd()
    if (rr < 0.25) k = "sev"; else if (rr < 0.4) k = "severity"
    if (i % 17 == 0)
      printf "%s=%s component=queue msg=\"retry, with \\\"quotes\\\" %d\" attempts=%d\n", k, lvl, i, (i % 3) + 1
    else if (i % 23 == 0)
      printf "component=worker level=nope severity=%s task=cleanup id=%d\n", lvl, i
    else
      printf "%s=%s component=http path=/api/v%d status=200 dur_ms=%d req_id=%06x\n", k, lvl, (i % 4) + 1, int(rnd()*900) + 10, int(rnd()*1048576)
  }'

# ----------------------------------------------------------------- docker
# Docker json-file driver: {"log": ...}; inner log is plain text, an embedded
# logback line, or an embedded JSON object (depth-1 recursion case).
gen docker 120 '
  for (i = 1; i <= n; i++) {
    r = rnd(); lvl = "info"
    if      (r < 0.05) lvl = "warn"
    else if (r < 0.07) lvl = "error"
    if (i % 31 == 0)
      printf "{\"log\":\"2026-11-09 10:%02d:%02d.123 %s from-inside-container task %d\",\"stream\":\"stdout\",\"time\":\"2026-11-09T10:%02d:%02d.123456789Z\"}\n", i % 60, i % 60, lvl, i, i % 60, i % 60
    else if (i % 19 == 0)
      printf "{\"log\":\"{\\\"level\\\":\\\"%s\\\",\\\"msg\\\":\\\"nested docker log %d\\\"}\",\"stream\":\"stderr\",\"time\":\"2026-11-09T10:%02d:%02d.5Z\"}\n", lvl, i, i % 60, (i * 7) % 60
    else if (i % 13 == 0)
      printf "{\"log\":\"plain container chatter %d, no level\",\"stream\":\"stdout\",\"time\":\"2026-11-09T10:%02d:%02d.5Z\"}\n", i, i % 60, (i * 3) % 60
    else
      printf "{\"log\":\"%s container heartbeat %d service=api\\n\",\"stream\":\"stdout\",\"time\":\"2026-11-09T10:%02d:%02d.25Z\"}\n", lvl, i, i % 60, (i * 11) % 60
  }'

# ------------------------------------------------------------------ mixed
# Interleaved dialects in ONE stream (auto latch/memo + fall-through + ANSI
# stripping + a blank line). Dialect rotates i%7; line #41k is blank.
gen mixed 150 '
  esc = sprintf("%c", 27)
  for (i = 1; i <= n; i++) {
    d = i % 7
    r = rnd(); lvl = "info"
    if      (r < 0.08) lvl = "warn"
    else if (r < 0.10) lvl = "error"
    if (i % 41 == 0) { print ""; continue }                       # blank line
    if (d == 0)
      printf "2026-11-09 10:%02d:%02d,123 %s com.acme.mixed.Service - mixed logback %d\n", i % 60, (i * 7) % 60, lvl, i
    else if (d == 1)
      printf "{\"level\":\"%s\",\"logger\":\"mixed.json\",\"msg\":\"mixed json %d\"}\n", lvl, i
    else if (d == 2)
      printf "level=%s component=mixed msg=\"mixed logfmt %d\"\n", lvl, i
    else if (d == 3)
      printf "{\"log\":\"mixed docker line %d with %s word\",\"stream\":\"stdout\"}\n", i, lvl
    else if (d == 4)
      printf "%s[31m%s colored keyword line %d%s[0m\n", esc, lvl, i, esc     # ANSI + keyword leg
    else if (d == 5)
      printf "plain neutral chatter %d carries no level word at all\n", i
    else
      printf "2026-11-09T10:%02d:%02d.500Z %s mixed iso-timestamp %d\n", i % 60, (i * 13) % 60, lvl, i
  }'

# ------------------------------------------------------------------ storm
# Error flood (S9 storm fixture): 49/50 ERROR pins severity at 1.0; ~2% info
# heartbeat. NO rnd() — bytes are seed-independent by construction.
gen storm 2000 '
  for (i = 1; i <= n; i++) {
    if (i % 50 == 0)
      printf "2026-11-09 10:%02d:%02d,000 INFO still-alive heartbeat %d\n", (i / 3000) % 60, (i / 50) % 60, i
    else
      printf "2026-11-09 10:%02d:%02d,000 ERROR com.acme.broken.Handler - unhandled boom %d\n", (i / 3000) % 60, (i / 34) % 60, i
  }'

printf 'generated 6 fixtures into %s (seed %s)\n' "$OUT" "$SEED"
